PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS groups(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, color TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', church TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', schedule TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1,photo TEXT NOT NULL DEFAULT '',maps_url TEXT NOT NULL DEFAULT '',maps_embed_url TEXT NOT NULL DEFAULT '',hero_title TEXT NOT NULL DEFAULT '',hero_description TEXT NOT NULL DEFAULT '',verse_mode TEXT NOT NULL DEFAULT 'daily',custom_verses TEXT NOT NULL DEFAULT '[]',founded_date TEXT NOT NULL DEFAULT '',anniversary_note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, admin INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS assignments(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), group_id INTEGER NOT NULL REFERENCES groups(id), role TEXT NOT NULL, period TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS records(id INTEGER PRIMARY KEY, module TEXT NOT NULL, group_id INTEGER NOT NULL REFERENCES groups(id), data TEXT NOT NULL, author_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS records_scope ON records(module,group_id);
CREATE TABLE IF NOT EXISTS participation(id INTEGER PRIMARY KEY, record_id INTEGER NOT NULL REFERENCES records(id) ON DELETE CASCADE, member_id INTEGER NOT NULL REFERENCES records(id) ON DELETE CASCADE, status TEXT NOT NULL, UNIQUE(record_id,member_id));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), group_id INTEGER REFERENCES groups(id), action TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(email TEXT NOT NULL, created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS grants(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), group_id INTEGER NOT NULL REFERENCES groups(id), module TEXT NOT NULL, can_write INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1);

CREATE TABLE IF NOT EXISTS albums(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES groups(id),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',visibility TEXT NOT NULL DEFAULT 'public',created_by INTEGER NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media_files(id INTEGER PRIMARY KEY,group_id INTEGER NOT NULL REFERENCES groups(id),album_id INTEGER REFERENCES albums(id),record_id INTEGER REFERENCES records(id) ON DELETE SET NULL,title TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('Afiche','Fotografía')),filename TEXT NOT NULL DEFAULT '',static_name TEXT NOT NULL DEFAULT '',width INTEGER NOT NULL,height INTEGER NOT NULL,uploaded_by INTEGER NOT NULL REFERENCES users(id),visibility TEXT NOT NULL DEFAULT 'internal',created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS media_organization ON media_files(group_id,created);
CREATE TABLE IF NOT EXISTS memberships(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL UNIQUE REFERENCES users(id),group_id INTEGER NOT NULL REFERENCES groups(id),status TEXT NOT NULL DEFAULT 'Pendiente',created TEXT NOT NULL,reviewed_by INTEGER REFERENCES users(id),reviewed TEXT);
CREATE TABLE IF NOT EXISTS community_messages(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),group_id INTEGER NOT NULL REFERENCES groups(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Pendiente',created TEXT NOT NULL,reviewed_by INTEGER REFERENCES users(id),reviewed TEXT);
CREATE TABLE IF NOT EXISTS leader_profiles(user_id INTEGER NOT NULL REFERENCES users(id),group_id INTEGER NOT NULL REFERENCES groups(id),message TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',photo TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 0,featured INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,group_id));

CREATE TABLE IF NOT EXISTS site_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS member_profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id),message TEXT NOT NULL DEFAULT '',verse_ref TEXT NOT NULL DEFAULT '',verse_text TEXT NOT NULL DEFAULT '',likes TEXT NOT NULL DEFAULT '',gifts TEXT NOT NULL DEFAULT '',dislikes TEXT NOT NULL DEFAULT '',avatar TEXT NOT NULL DEFAULT 'luz',photo TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'Pendiente',updated TEXT NOT NULL,reviewed_by INTEGER REFERENCES users(id),reviewed TEXT NOT NULL DEFAULT '',demo INTEGER NOT NULL DEFAULT 0,birthday_md TEXT NOT NULL DEFAULT '',birthday_public INTEGER NOT NULL DEFAULT 0);
